// Package golang is the template set of the Go client. It turns the model of
// an API description into Go source that uses only net/http and
// encoding/json.
//
// The generated files are the models, the operations, the metadata of the
// client and the operation table of the conformance adapter. The transport of
// the client and the message loop of the adapter are hand-written. They are
// not part of the output.
//
// The generated bytes are identical across machines only when the Go
// formatting toolchain is the same, because generation uses go/format.
package golang

import (
	"bytes"
	"embed"
	"fmt"
	"go/format"
	"path"
	"regexp"
	"slices"
	"strings"
	"text/template"

	"opendustpan.org/opendustpan/internal/clientgen"
	"opendustpan.org/opendustpan/internal/clientgen/model"
)

//go:embed templates/*.tmpl
var templateFS embed.FS

// importPath is the shape of the module path of a client, for example
// opendustpan.org/client.
var importPath = regexp.MustCompile(`^[a-z0-9]+([.-][a-z0-9]+)*(/[a-z0-9]+([._-][a-z0-9]+)*)*$`)

// packageName is the shape of the name of a Go package.
var packageName = regexp.MustCompile(`^[a-z][a-z0-9]*$`)

// Generated file paths, relative to the output directory.
const (
	pathModels     = "models.go"
	pathOperations = "operations.go"
	pathMetadata   = "metadata.go"
	pathAdapter    = "cmd/conformance-adapter/operations.go"
)

// language is the Go template set.
type language struct{}

// New returns the Go template set.
func New() clientgen.Language { //nolint:ireturn // The port is the contract; callers do not depend on the type.
	return language{}
}

// Name implements clientgen.Language.
func (language) Name() string { return "go" }

// Render implements clientgen.Language. The files are in the order of their
// paths.
func (language) Render(api *model.API, opts clientgen.Options) ([]clientgen.File, error) {
	d, err := newData(api, opts)
	if err != nil {
		return nil, err
	}

	tmpl, err := template.New("go").Funcs(funcs()).ParseFS(templateFS, "templates/*.tmpl")
	if err != nil {
		return nil, fmt.Errorf("go templates: %w", err)
	}

	outputs := []struct{ path, template string }{
		{pathAdapter, "adapter.go.tmpl"},
		{pathMetadata, "metadata.go.tmpl"},
		{pathModels, "models.go.tmpl"},
		{pathOperations, "operations.go.tmpl"},
	}

	files := make([]clientgen.File, 0, len(outputs))

	for _, out := range outputs {
		var buf bytes.Buffer
		if err = tmpl.ExecuteTemplate(&buf, out.template, d); err != nil {
			return nil, fmt.Errorf("go template %s: %w", out.template, err)
		}

		src, fmtErr := format.Source(buf.Bytes())
		if fmtErr != nil {
			return nil, fmt.Errorf("go template %s gave source that Go cannot read: %w", out.template, fmtErr)
		}

		files = append(files, clientgen.File{Path: out.path, Content: src})
	}

	slices.SortFunc(files, func(a, b clientgen.File) int { return strings.Compare(a.Path, b.Path) })

	return files, nil
}

// generatedHeader is the header of a file of this generator. It has the name
// of the generator, so that the generated files of other tools do not match.
// It must be the first line of the file: a hand-written file that quotes the
// header on a later line is not generated, and the writer must not delete it.
// The generator writes no byte order mark, so nothing may come before it.
var generatedHeader = regexp.MustCompile(
	`\A// Code generated by clientgen \S+ from API description \S+\. DO NOT EDIT\.\r?(?:\n|\z)`,
)

// header writes the header line of a generated file.
func header(generatorVersion, descriptionVersion string) string {
	return "// Code generated by clientgen " + generatorVersion + " from API description " +
		descriptionVersion + ". DO NOT EDIT."
}

// Header implements clientgen.Language.
func (language) Header(opts clientgen.Options, descriptionVersion string) string {
	return header(opts.GeneratorVersion, descriptionVersion)
}

// IsGenerated implements clientgen.Language.
func (language) IsGenerated(head []byte) bool { return generatedHeader.Match(head) }

// Owned implements clientgen.Language. The Go client shares its package and
// the directory of its adapter with hand-written files (the transport and the
// main package of the adapter), so the run owns no path, and a file that the
// run does not give is stale only by its header.
func (language) Owned(string) bool { return false }

// funcs are the encoders that a template calls. A value from the description
// goes into source through one of them only.
func funcs() template.FuncMap {
	return template.FuncMap{
		"goString": goString,
		"comment":  comment,
		"typeDoc":  typeDoc,
		"opDoc":    opDoc,
		"join":     strings.Join,
	}
}

// typeDoc writes the comment of a type.
func typeDoc(name, doc string) string {
	if strings.TrimSpace(doc) == "" {
		return comment("", name+" is a schema of the API description.")
	}

	return comment("", doc)
}

// opDoc writes the comment of a method of the client.
func opDoc(method, id, doc string) string {
	head := comment("", method+" calls the operation "+id+".")
	if strings.TrimSpace(doc) == "" {
		return head
	}

	return head + "//\n" + comment("", doc)
}

// data is what the templates read.
type data struct {
	// Header is the first line of each generated file.
	Header string
	// Package is the name of the Go package of the client.
	Package string
	// Import is the import path of the client, for the adapter.
	Import             string
	ClientVersion      string
	DescriptionVersion string
	ServerRelease      string
	GeneratorVersion   string
	Title              string
	Types              []typeView
	Operations         []operationView
	// seen holds the package-level names that the schemas and the query types
	// take.
	seen map[string]string
	// NeedsURL and NeedsFmt say which imports operations.go needs.
	NeedsURL bool
	NeedsFmt bool
	// HasChoice says that a schema holds a field with a type list, so that
	// models.go needs the jsonKind helper.
	HasChoice bool
	// NeedsInteger says that a type list holds integer and no number, so that
	// models.go needs the jsonInteger helper.
	NeedsInteger bool
}

type typeView struct {
	Name   string
	Doc    string
	IsEnum bool
	Open   bool
	Values []enumValue
	Fields []fieldView
	// Required lists the wire names of the required fields.
	Required []string
	// NotNull lists the wire names of the required fields that cannot be null.
	NotNull []string
	// Choice lists the JSON types that a field with a type list accepts, in
	// the order of the list, with no repeat. Such a type holds the bytes of
	// the value and checks its type in UnmarshalJSON.
	Choice []string
	// Integer says that the list holds integer and no number: the JSON number
	// type is accepted only when it holds an integer.
	Integer bool
	// ChoiceText names the JSON types of a choice for an error message.
	ChoiceText string
}

// HasChoice reports whether the type is the named type of a type list.
func (t typeView) HasChoice() bool { return len(t.Choice) > 0 }

type enumValue struct {
	Const string
	Value string
}

type fieldView struct {
	Name string
	Type string
	Tag  string
	Doc  string
}

type paramView struct {
	// Ident is the name of the Go parameter.
	Ident string
	Type  string
	Wire  string
}

type queryView struct {
	Field string
	Wire  string
	// Mode is many (a list), ptr (an optional scalar) or value (a required
	// scalar).
	Mode string
}

type operationView struct {
	ID          string
	Method      string
	Doc         string
	HTTPMethod  string
	PathExpr    string
	Params      []paramView
	QueryType   string
	QueryFields []fieldView
	Query       []queryView
	// Body is the Go type of the body in the client package, and
	// AdapterBody is the same type as the adapter writes it.
	Body         string
	AdapterBody  string
	BodyPointer  bool
	BodyRequired bool
	MediaType    string
	// Result is the declared type of the answer, and ResultReturn is the
	// type that the method returns.
	Result       string
	ResultReturn string
	ResultKind   string
	Public       bool
	Idempotent   bool
	IfMatch      string
	ETag         bool
	// Statuses are the success statuses as Go integer literals, joined with
	// commas.
	Statuses string
}

// newData checks the options, and builds the views of the model.
func newData(api *model.API, opts clientgen.Options) (*data, error) {
	if !importPath.MatchString(opts.Package) {
		return nil, fmt.Errorf("%w: package %q", clientgen.ErrInvalidName, opts.Package)
	}

	pkg := path.Base(opts.Package)
	if !packageName.MatchString(pkg) {
		return nil, fmt.Errorf("%w: package name %q", clientgen.ErrInvalidName, pkg)
	}

	tokens := []struct{ what, value string }{
		{"description version", api.Version},
		{"client version", opts.ClientVersion},
		{"server release", opts.ServerRelease},
		{"generator version", opts.GeneratorVersion},
	}

	for _, tok := range tokens {
		if err := clientgen.CheckToken(tok.what, tok.value); err != nil {
			return nil, err
		}
	}

	if err := clientgen.CheckClientVersion(api.Version, opts.ClientVersion); err != nil {
		return nil, err
	}

	d := new(data)
	d.Header = header(opts.GeneratorVersion, api.Version)
	d.Package, d.Import, d.Title = pkg, opts.Package, api.Title
	d.ClientVersion, d.DescriptionVersion = opts.ClientVersion, api.Version
	d.ServerRelease, d.GeneratorVersion = opts.ServerRelease, opts.GeneratorVersion

	if err := clientgen.CheckModel(api); err != nil {
		return nil, err
	}

	if err := d.addTypes(api); err != nil {
		return nil, err
	}

	if err := d.addOperations(api); err != nil {
		return nil, err
	}

	return d, nil
}

// addTypes builds the views of the schemas.
func (d *data) addTypes(api *model.API) error {
	seen := make(map[string]string)

	for _, name := range reservedTypes() {
		seen[name] = transportOwner
	}

	d.seen = seen

	for i := range api.Schemas {
		s := &api.Schemas[i]

		// The Go client reads an error answer as the base error schema. It
		// writes no union and no schema that only a union uses.
		if s.Kind == model.KindUnion || s.Union != "" {
			continue
		}

		if err := claim(seen, s.Name, "schema "+s.Name); err != nil {
			return err
		}

		var (
			tv  typeView
			err error
		)

		switch s.Kind {
		case model.KindEnum:
			tv, err = enumView(s, seen)
		case model.KindObject:
			tv, err = d.objectView(s)
		case model.KindUnion:
			// Defense in depth: the check above skips a union. This case stays so that a
			// change of that check cannot make the set write a type it has no code for.
			err = fmt.Errorf("%w: schema %s is a union, which the Go template set does not write",
				clientgen.ErrUnsupported, s.Name)
		default:
			err = fmt.Errorf("%w: schema %s has an unknown kind", clientgen.ErrInvalidDescription, s.Name)
		}

		if err != nil {
			return err
		}

		d.Types = append(d.Types, tv)
	}

	return nil
}

// transportOwner names the hand-written transport as the owner of a name.
const transportOwner = "the transport of the client"

// claim records that a name is taken, and returns ErrInvalidName when it was
// taken before.
func claim(seen map[string]string, name, by string) error {
	if prev, ok := seen[name]; ok {
		return fmt.Errorf("%w: %s clashes with %s in the Go package", clientgen.ErrInvalidName, by, prev)
	}

	seen[name] = by

	return nil
}

// enumView builds the view of an enum with a constant for each value.
func enumView(s *model.Schema, seen map[string]string) (typeView, error) {
	var tv typeView

	tv.Name, tv.Doc, tv.IsEnum, tv.Open = s.Name, s.Description, true, s.Open

	for _, v := range s.Values {
		c := s.Name + pascal(v)

		if err := claim(seen, c, "enum value "+v+" of "+s.Name); err != nil {
			return typeView{}, err
		}

		tv.Values = append(tv.Values, enumValue{Const: c, Value: v})
	}

	return tv, nil
}

// objectView builds the view of an object schema as a struct.
func (d *data) objectView(s *model.Schema) (typeView, error) {
	var tv typeView

	tv.Name, tv.Doc = s.Name, s.Description

	if s.Extra != nil {
		return typeView{}, fmt.Errorf(
			"%w: schema %s has additional properties, which the Go template set does not write",
			clientgen.ErrUnsupported, s.Name,
		)
	}

	names := make(map[string]string)
	names["UnmarshalJSON"] = "the method UnmarshalJSON"

	for i := range s.Fields {
		f := &s.Fields[i]
		ident := exported(f.Name)

		if err := claim(names, ident, "field "+f.Name+" of "+s.Name); err != nil {
			return typeView{}, err
		}

		typ, err := d.fieldType(s.Name, *f)
		if err != nil {
			return typeView{}, err
		}

		tag := f.Name
		if !f.Required {
			tag += ",omitempty"
		}

		tv.Fields = append(tv.Fields, fieldView{
			Name: ident,
			Type: typ,
			Tag:  "`json:" + goString(tag) + "`",
			Doc:  f.Description,
		})

		if f.Required {
			tv.Required = append(tv.Required, f.Name)

			if !f.Type.Nullable {
				tv.NotNull = append(tv.NotNull, f.Name)
			}
		}
	}

	return tv, nil
}

// fieldType writes the Go type of one field of an object. A type list gets a
// named type: the name of the schema and the name of the field make its name,
// in the naming rules of this template set. An optional field takes a pointer
// to it, because the zero value of the named type is empty and would write
// nothing.
func (d *data) fieldType(schemaName string, f model.Field) (string, error) {
	if f.Type.Kind == model.TypeUnion {
		name := schemaName + exported(f.Name)

		if err := claim(d.seen, name, "the type of field "+f.Name+" of "+schemaName); err != nil {
			return "", err
		}

		tv, err := choiceView(name, f.Type)
		if err != nil {
			return "", fmt.Errorf("field %s of %s: %w", f.Name, schemaName, err)
		}

		d.Types = append(d.Types, tv)
		d.HasChoice = true
		d.NeedsInteger = d.NeedsInteger || tv.Integer

		if f.Required {
			return name, nil
		}

		return "*" + name, nil
	}

	// Defense in depth: the check of the model refuses a type list that no
	// template can write, and this check keeps the type list of a field out
	// of the Go type of a list or a map, where the generated code would
	// carry it as any JSON value.
	if clientgen.HoldsTypeList(f.Type) {
		return "", fmt.Errorf(
			"%w: the field %s of %s holds a type list in a list or a map, which the Go template set does not write",
			clientgen.ErrUnsupported, f.Name, schemaName,
		)
	}

	return typeExpr(f.Type, fieldPresence(f), ""), nil
}

// choiceView builds the view of a type list as a named type.
func choiceView(name string, t model.Type) (typeView, error) {
	var tv typeView

	tv.Name = name

	for _, m := range t.Members {
		typ, err := choiceMember(m)
		if err != nil {
			return typeView{}, err
		}

		if slices.Contains(tv.Choice, typ) {
			continue
		}

		tv.Choice = append(tv.Choice, typ)
	}

	if len(tv.Choice) == 0 {
		return typeView{}, fmt.Errorf("%w: the type list of %s has no member", clientgen.ErrUnsupported, name)
	}

	// JSON holds one number type, so an integer and a number take one name in
	// the list of the accepted JSON types. A list that holds integer and no
	// number takes only the integers of that type.
	tv.Integer = slices.Contains(t.Members, model.TypeInteger) && !slices.Contains(t.Members, model.TypeNumber)

	texts := make([]string, 0, len(tv.Choice))

	for _, typ := range tv.Choice {
		if typ == numberType && tv.Integer {
			texts = append(texts, "an integer")

			continue
		}

		texts = append(texts, "a "+typ)
	}

	tv.ChoiceText = joinText(texts)
	tv.Doc = name + " holds " + tv.ChoiceText + "."

	return tv, nil
}

// choiceMember names the JSON type that holds one kind of a type list. JSON
// holds one number type, so an integer and a number give the same name.
func choiceMember(kind model.TypeKind) (string, error) {
	names := map[model.TypeKind]string{
		model.TypeString:  stringType,
		model.TypeInteger: numberType,
		model.TypeNumber:  numberType,
		model.TypeBoolean: "boolean",
	}

	name, ok := names[kind]
	if !ok {
		return "", fmt.Errorf("%w: a type list holds the kind %d", clientgen.ErrUnsupported, kind)
	}

	return name, nil
}

// minJoinedTexts is the smallest number of texts that joinText joins with a
// comma and an or.
const minJoinedTexts = 2

// joinText joins the names of the accepted types of a type list, as in
// "a string, a number or a boolean".
func joinText(texts []string) string {
	if len(texts) < minJoinedTexts {
		return strings.Join(texts, "")
	}

	return strings.Join(texts[:len(texts)-1], ", ") + " or " + texts[len(texts)-1]
}

// fieldPresence says whether a field is required or optional.
func fieldPresence(f model.Field) presence {
	if f.Required {
		return required
	}

	return optional
}

// parameterPresence says whether a parameter is required or optional.
func parameterPresence(p model.Parameter) presence {
	if p.Required {
		return required
	}

	return optional
}

// presence says whether a member of an object can be absent.
type presence int

const (
	_ presence = iota // Zero means that nobody chose.
	// required means that the object always holds the member.
	required
	// optional means that the member can be absent.
	optional
)

// rawMessage is the Go type of any JSON value.
const rawMessage = "json.RawMessage"

// stringType is the name of the JSON type of a string, and of the Go type that
// holds one.
const stringType = "string"

// numberType is the name of the JSON type of a number.
const numberType = "number"

// typeExpr writes a model type as a Go type. A value that can be absent or
// null is a pointer, where the zero value of the type is also a value. qual is
// the package qualifier of a named schema, for example "client.", or empty.
func typeExpr(t model.Type, p presence, qual string) string {
	base := baseExpr(t, qual)

	if needsPointer(t, p) {
		return "*" + base
	}

	return base
}

// needsPointer says that the Go type of a value is a pointer. A list or a map
// is a pointer only when it can be null, because a nil list says that the
// member is absent. Any JSON value is never a pointer, because json.RawMessage
// holds null.
func needsPointer(t model.Type, p presence) bool {
	if t.Kind == model.TypeAny {
		return false
	}

	if t.Kind == model.TypeArray || t.Kind == model.TypeMap {
		return t.Nullable
	}

	return t.Nullable || p == optional
}

// baseExpr writes the Go type of a model type with no pointer on it.
func baseExpr(t model.Type, qual string) string {
	if t.Kind == model.TypeArray {
		return "[]" + elemExpr(t, qual)
	}

	if t.Kind == model.TypeMap {
		return "map[string]" + elemExpr(t, qual)
	}

	if t.Kind == model.TypeRef {
		return qual + t.Ref
	}

	return scalarExpr(t.Kind)
}

// scalarExpr writes the Go type of a scalar. Any other kind is any JSON value.
// The callers refuse a type list before this point: a type list becomes a
// named type of its own.
func scalarExpr(k model.TypeKind) string {
	names := map[model.TypeKind]string{
		model.TypeString: stringType, model.TypeInteger: "int64", model.TypeNumber: "float64",
		model.TypeBoolean: "bool",
	}

	if name, ok := names[k]; ok {
		return name
	}

	return rawMessage
}

// elemExpr writes the type of the items of an array or the values of a map.
// An item that can be null is a pointer.
func elemExpr(t model.Type, qual string) string {
	if t.Elem == nil {
		return rawMessage
	}

	return typeExpr(*t.Elem, required, qual)
}
